#include <stdio.h>

int main(void)
{
    int a[] = {3, 1, 2};
    for (int i = 0; i < 2; ++i) {
        if (a[i] > a[i + 1]) {
            int saved = a[i];
            a[i] = a[i + 1];
            a[i + 1] = saved;
        }
    }
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

